document.addEventListener("DOMContentLoaded", () => {

  /* ========= عناصر المشغل ========= */
  const overlay      = document.getElementById("playerOverlay");
  const titleEl      = document.getElementById("playerTitle");
  const videoEl      = document.getElementById("playerVideo");
  const iframeEl     = document.getElementById("playerIframe");
  const closeBtn     = document.getElementById("playerClose");

  const episodesRow  = document.getElementById("episodesRow");
  const episodesList = document.getElementById("episodesList");

  const latestBtn     = document.getElementById("latestBtn");
  const latestOverlay = document.getElementById("latestOverlay");
  const latestGrid    = document.getElementById("latestGrid");
  const latestClose   = document.getElementById("latestClose");

  /* ========= أدوات ========= */
  function clearPlayer() {
    videoEl.pause();
    videoEl.removeAttribute("src");
    iframeEl.removeAttribute("src");
    videoEl.style.display = "none";
    iframeEl.style.display = "none";
  }

  function play(url, title) {
    if (!url) return;

    clearPlayer();
    titleEl.textContent = title || "";

    if (/\.(mp4|m3u8|ts)(\?|$)/i.test(url)) {
      videoEl.src = url;
      videoEl.style.display = "block";
    } else {
      iframeEl.src = url;
      iframeEl.style.display = "block";
    }
  }

  function openPlayer() {
    overlay.classList.add("active");
  }

  function closePlayer() {
    overlay.classList.remove("active");
    clearPlayer();
    episodesList.innerHTML = "";
    episodesRow.style.display = "none";
  }

  closeBtn.onclick = closePlayer;

  /* ========= كروت المكتبة ========= */
  document.querySelectorAll(".video-card").forEach(card => {

    card.addEventListener("click", () => {

      const title = card.dataset.title || "";
      const movieUrl = card.dataset.video || "";
      const eps = card.querySelectorAll(".ep-data");

      openPlayer();
      episodesList.innerHTML = "";
      episodesRow.style.display = "none";

      // 🎬 فيلم
      if (!eps.length) {
        play(movieUrl, title);
        return;
      }

      // 📺 مسلسل
      episodesRow.style.display = "flex";

      eps.forEach((ep, i) => {
        const btn = document.createElement("button");
        btn.className = "ep-pill";
        btn.textContent = ep.dataset.label || `حلقة ${i + 1}`;

        btn.onclick = () => {
          episodesList.querySelectorAll(".ep-pill")
            .forEach(b => b.classList.remove("active"));
          btn.classList.add("active");
          play(ep.dataset.video, `${title} — ${btn.textContent}`);
        };

        episodesList.appendChild(btn);
      });

      // تشغيل آخر حلقة تلقائيًا
      const lastBtn = episodesList.lastElementChild;
      lastBtn.classList.add("active");
      play(
        eps[eps.length - 1].dataset.video,
        `${title} — ${lastBtn.textContent}`
      );

      lastBtn.scrollIntoView({ behavior: "smooth", inline: "end" });
    });

  });

  /* ========= زر 🔥 المضاف حديثاً ========= */
  if (latestBtn && latestOverlay && latestGrid) {

    latestBtn.addEventListener("click", () => {
      latestGrid.innerHTML = "";

      const latestItems = [];

      document.querySelectorAll(".video-card").forEach(card => {
        const title = card.dataset.title || "بدون عنوان";
        const img   = card.querySelector("img")?.src;

        const eps = card.querySelectorAll(".ep-data");

        // 🆕 من الحلقات
        eps.forEach(ep => {
          const label = ep.dataset.label || "";
          if (!label.includes("🆕")) return;

          latestItems.push({
            title,
            img,
            label,
            video: ep.dataset.video
          });
        });

        // 🆕 من اسم الفيلم
        if (card.dataset.video && title.includes("🆕")) {
          latestItems.push({
            title,
            img,
            label: "فيلم جديد",
            video: card.dataset.video
          });
        }
      });

      latestItems.forEach(item => {
        const box = document.createElement("div");
        box.style.cursor = "pointer";
        box.style.background = "#0b1220";
        box.style.borderRadius = "10px";
        box.style.overflow = "hidden";
        box.style.position = "relative";

        box.innerHTML = `
          <img src="${item.img}" style="width:100%;aspect-ratio:2/3;object-fit:cover">
          <span style="
            position:absolute;
            top:8px;left:8px;
            background:#dc2626;
            color:#fff;
            font-size:11px;
            padding:3px 7px;
            border-radius:999px;
            font-weight:700;
          ">${item.label}</span>
          <div style="padding:6px;font-size:13px">
            <b>${item.title}</b><br>
          </div>
        `;

        box.onclick = () => {
          latestOverlay.style.display = "none";
          openPlayer();
          play(item.video, `${item.title} — ${item.label}`);
        };

        latestGrid.appendChild(box);
      });

      latestOverlay.style.display = "block";
    });

    if (latestClose) {
      latestClose.onclick = () => {
        latestOverlay.style.display = "none";
      };
    }
  }

});
